// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.DELETE(options.BaseURL+"/connections/:connection_id/credentials", wrapper.DeleteCredentials)
	router.PUT(options.BaseURL+"/connections/:connection_id/credentials", wrapper.PutCredentials)
	router.POST(options.BaseURL+"/connections/:connection_id/authorize-url", wrapper.AuthorizeUrl)
	router.POST(options.BaseURL+"/connections/:connection_id/probe", wrapper.Probe)
	router.POST(options.BaseURL+"/connections/:connection_id/fetch", wrapper.Fetch)
	router.POST(options.BaseURL+"/connections/:connection_id/manifest", wrapper.Manifest)
	router.POST(options.BaseURL+"/connections/:connection_id/check-access", wrapper.CheckAccess)
	router.POST(options.BaseURL+"/connections/:connection_id/publish", wrapper.Publish)
	router.POST(options.BaseURL+"/connections/:connection_id/find-published", wrapper.FindPublished)
	router.POST(options.BaseURL+"/connections/:connection_id/webhooks/parse", wrapper.ParseWebhook)
}

